param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Read shipped XML and previously derived C# as data. No game code execution.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$out=Join-Path $root 'docs/research/rimworld/evidence'
$manifest=Get-Content (Join-Path $out 'dining-comfort-manifest.json') -Raw|ConvertFrom-Json
function Source([string]$file,[int]$start=1,[int]$end=0){
 $path=Join-Path $root $file;$lines=Get-Content -LiteralPath $path
 if(!$end){$end=$lines.Count};if($start -lt 1 -or $end -gt $lines.Count -or $end -lt $start){throw "Invalid range $file"}
 [ordered]@{file=$file;sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant();lines=@($start,$end)}
}
$f='.local-research/food';$h='.local-research/housing';$p='.local-research/dining-comfort'
$claims=@(
 [ordered]@{id='DC01';finding='Ingest is prepare -> chew -> finalize. Food must remain ingestible and reachable/carried; food pickup enters carry and changes targetA. Nutrition and item consumption occur at FinalizeIngest/Thing.Ingested, not when selecting a seat.';sources=@((Source "$f/RimWorld.JobDriver_Ingest.cs" 91 173),(Source "$f/RimWorld.Toils_Ingest.cs" 43 69),(Source "$f/RimWorld.Toils_Ingest.cs" 395 438));xml=@()},
 [ordered]@{id='DC02';finding='Tool users take food from inventory or walk to food and pick it up. Non-manipulating pawns and non-tool-users use distinct paths. Drafted tool users skip CarryIngestibleToChewSpot; this is not a universal always-go-to-table rule.';sources=@((Source "$f/RimWorld.JobDriver_Ingest.cs" 120 173));xml=@()},
 [ordered]@{id='DC03';finding='Seat search uses food chairSearchRadius. It first finds a reachable safe sittable with a free cell, same faction for player pawns, not forbidden/fogged/burning/hostile and socially proper. The seat cell must have a cardinally adjacent Eat surface. A standalone chair is not a normal dining-seat candidate.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 94 196));xml=@('DX01','DX02')},
 [ordered]@{id='DC04';finding='A chosen seat/standing cell is reserved plus a destination reservation, then reached by path. CanReserveSittableOrSpot checks forbidden/impassable cells and conflicting nearby interaction cells; multi-sittable furniture reserves its specific cell, ordinary chairs reserve the building.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 71 92),(Source "$p/Verse.AI.ReservationUtility.cs" 9 61));xml=@()},
 [ordered]@{id='DC05';finding='No safe eligible chair falls back to a standing chewing spot. Dangerous standing candidates can trigger a second chair search no more dangerous than that spot. Complete failure starts a path to the current cell and logs a warning, rather than making all eating impossible.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 71 134),(Source "$p/RimWorld.RCellFinder.cs" 1018 1138));xml=@()},
 [ordered]@{id='DC06';finding='FindAdjacentEatSurface picks a cardinally adjacent Eat surface and faces it. Carried food can be rendered over that surface while the pawn is stationary; this draw position is not a drop, ground stack or table inventory transaction.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 227 291),(Source "$f/RimWorld.JobDriver_Ingest.cs" 238 263));xml=@()},
 [ordered]@{id='DC07';finding='Chewing duration is rounded baseIngestTicks times duration multiplier; multiplier is reciprocal EatingSpeed unless useEatingSpeedStat=false. Chewing stops movement, uses a physical interaction reservation for spawned food, releases that reservation on finish, and calls GainComfortFromCellIfPossible every tick interval.';sources=@((Source "$f/RimWorld.JobDriver_Ingest.cs" 41 53),(Source "$f/RimWorld.Toils_Ingest.cs" 294 353));xml=@('DX02')},
 [ordered]@{id='DC08';finding='Dining memories require mood, nutrition-giving food, and chairSearchRadius>10. AteWithoutTable additionally needs Standing, not WildMan, tableDesired, and no Eat surface immediately in front. Missing chair alone does not establish this memory; present tables elsewhere do not prevent it.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 395 417));xml=@('DX02','DX03')},
 [ordered]@{id='DC09';finding='AteWithoutTable lasts1day, stackLimit1, mood-3; Ascetic and the indicated Ideology precept nullify it. FinalizeIngest has no branch clearing an existing memory after later table use; memory age/refresh must be distinguished from mere presence in a save.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 395 438));xml=@('DX03')},
 [ordered]@{id='DC10';finding='Dining-room memory uses current room Impressiveness score stage and a non-null thought stage; this call does not test RoomRole DiningRoom, require a table/chair, or explicitly reject outdoor rooms. Stages0..2 are null; stages3..9 give+2..+8,1day,stackLimit1.';sources=@((Source "$f/RimWorld.Toils_Ingest.cs" 407 417));xml=@('DX04')},
 [ordered]@{id='DC11';finding='Comfort is a seeker need, not an instant chair bonus. CurInstantLevel uses clamped lastComfortUsed only while lastComfortUseTick>=TicksGame-15, otherwise0; category thresholds are0.1,0.6,0.7,0.8,0.9.';sources=@((Source "$h/RimWorld.Need_Comfort.cs"));xml=@('DX05')},
 [ordered]@{id='DC12';finding='GainComfortFromCell samples the building under the pawn on its15tick hash interval; acceptable nonnegative Comfort stats call ComfortUsed. Chewing uses this without chairsOnly. Furniture elsewhere in the room does not feed this method.';sources=@((Source "$h/RimWorld.PawnUtility.cs" 317 339),(Source "$f/RimWorld.Toils_Ingest.cs" 313 334));xml=@('DX01','DX06')},
 [ordered]@{id='DC13';finding='Need_Seeker moves toward its instant target by seekerRisePerHour*0.06 or seekerFallPerHour*0.06 per NeedInterval and clamps to the target; Comfort defines0.60/hour rise and0.04/hour fall. This does not fill comfort in one meal.';sources=@((Source "$h/RimWorld.Need_Seeker.cs"));xml=@('DX05')},
 [ordered]@{id='DC14';finding='NeedComfort is a situation thought: Uncomfortable gives-3; Normal is inactive; higher categories give+4,+6,+8,+10. It is distinct from the time-limited AteWithoutTable and AteInImpressiveDiningRoom memories.';sources=@((Source "$p/RimWorld.ThoughtWorker_NeedComfort.cs"),(Source "$h/RimWorld.Need_Comfort.cs"));xml=@('DX07')},
 [ordered]@{id='DC15';finding='Selected base furniture: Stool comfort0.5/stuff25/work450; DiningChair0.70/45/8000; Armchair0.8/110/14000; Table1x2c stuff28/work750 inherits Eat surface. Quality factors for Comfort are0.76/0.88/1/1.12/1.24/1.45/1.7. Material/quality/effective modded values are separate.';sources=@((Source "$h/RimWorld.PawnUtility.cs" 329 339));xml=@('DX01','DX06')},
 [ordered]@{id='DC16';finding='IngestibleProperties defaults: baseIngestTicks500,chairSearchRadius32,useEatingSpeedStat=true,ingestHoldUsesTable=true,tableDesired=true. XML children can override these; the selected meals and their parent chain are retained separately.';sources=@((Source '.local-research/survival/RimWorld.IngestibleProperties.cs' 7 61));xml=@('DX02')},
 [ordered]@{id='DC17';finding='Interruption before FinalizeIngest does not execute its nutrition/memory settlement. Ordinary EndCurrentJob cleanup releases job reservations and runs driver cleanup; carried objects are dropped near the pawn unless carryThingAfterJob or a transition override preserves them. Suspension/queued-job branches can retain reservations and must not be conflated with a finished job.';sources=@((Source '.local-research/work/Verse.AI.Pawn_JobTracker.cs' 402 522),(Source "$f/RimWorld.Toils_Ingest.cs" 338 351),(Source "$f/RimWorld.Toils_Ingest.cs" 395 438));xml=@()}
)
$specs=@(
 @('DX01','Data/Core/Defs/ThingDefs_Buildings/Buildings_Furniture.xml','/Defs/ThingDef[@Name="FurnitureBase" or @Name="FurnitureWithQualityBase" or @Name="ArtableFurnitureBase" or @Name="TableBase" or @Name="TableGatherSpotBase" or defName="Stool" or defName="DiningChair" or defName="Armchair" or defName="Table1x2c"]'),
 @('DX02','Data/Core/Defs/ThingDefs_Items/Items_Food.xml','/Defs/ThingDef[@Name="MealBaseIngredientless" or @Name="MealBase" or @Name="MealCookedIngredientless" or @Name="MealCooked" or defName="MealSimple" or defName="MealSurvivalPack"]'),
 @('DX03','Data/Core/Defs/ThoughtDefs/Thoughts_Memory_Misc.xml','/Defs/ThoughtDef[defName="AteWithoutTable"]'),
 @('DX04','Data/Core/Defs/ThoughtDefs/Thoughts_Memory_RoomStats.xml','/Defs/ThoughtDef[defName="AteInImpressiveDiningRoom"]'),
 @('DX05','Data/Core/Defs/NeedDefs/Needs.xml','/Defs/NeedDef[defName="Comfort"]'),
 @('DX06','Data/Core/Defs/Stats/Stats_Basics_General.xml','/Defs/StatDef[defName="Comfort"]'),
 @('DX07','Data/Core/Defs/ThoughtDefs/Thoughts_Situation_Needs.xml','/Defs/ThoughtDef[defName="NeedComfort"]')
)
$keep=@('defName','thingClass','category','passability','pathCost','fillPercent','costStuffCount','stuffCategories','surfaceType','size','hasInteractionCell','interactionCellOffset','durationDays','stackLimit','nullifyingTraits','nullifyingPrecepts','workerClass','needClass','minIntelligence','colonistAndPrisonersOnly','seekerRisePerHour','seekerFallPerHour','defaultBaseValue','minValue','maxValue','parts','validWhileDespawned','developmentalStageFilter')
$nested=@{statBases=@('MaxHitPoints','WorkToBuild','Comfort','Nutrition','Beauty');building=@('isSittable','multiSittable');ingestible=@('baseIngestTicks','chairSearchRadius','useEatingSpeedStat','ingestHoldUsesTable','tableDesired','maxNumToIngestAtOnce','preferability','foodType')}
$xml=@(foreach($spec in $specs){
 $path=Join-Path $GameRoot $spec[1];$doc=[xml](Get-Content -LiteralPath $path -Raw);$nodes=$doc.SelectNodes($spec[2]);if(!$nodes.Count){throw "Empty XPath $($spec[0])"}
 $selected=@(foreach($node in $nodes){
  $copy=$node.CloneNode($false)
  foreach($child in $node.ChildNodes){
   if($child.LocalName -in $keep){[void]$copy.AppendChild($child.CloneNode($true))}
   elseif($nested.ContainsKey($child.LocalName)){$subcopy=$child.CloneNode($false);foreach($sub in $child.ChildNodes){if($sub.LocalName -in $nested[$child.LocalName]){[void]$subcopy.AppendChild($sub.CloneNode($true))}};[void]$copy.AppendChild($subcopy)}
   elseif($child.LocalName -eq 'stages'){$stages=$child.CloneNode($false);foreach($li in $child.SelectNodes('li')){$lc=$li.CloneNode($false);foreach($s in $li.ChildNodes){if($s.LocalName -eq 'baseMoodEffect'){[void]$lc.AppendChild($s.CloneNode($true))}};[void]$stages.AppendChild($lc)};[void]$copy.AppendChild($stages)}
  };$copy.OuterXml
 })
 [ordered]@{id=$spec[0];file=$spec[1];source_sha256=(Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant();xpath=$spec[2];projection='Original attributes and selected gameplay children only; stages retain null markers and mood values, not descriptive text';nodes=$selected}
})
$prior=Get-Content (Join-Path $out 'animal-pens-evidence.json') -Raw|ConvertFrom-Json
$e=[ordered]@{evidence_id='RW17-DINING-COMFORT-MECHANISMS';date_local='2026-11-04';version_text=$manifest.version_text;source_sha256=$manifest.source_sha256;kind='Static ILSpy-derived C# and selected Core XML; native observations documented separately';manifest='dining-comfort-manifest.json';types='dining-comfort-types.json';claims=$claims;xml=$xml;rea_members=$prior.rea_members;native_runtime_report='../95-native-dining-runtime.md';limitations=@('Derived C# is not original source; unresolved dependencies were tolerated.','Existing matching reconstruction is reused; only3 missing types were newly extracted.','REA67108864byte member budget failure was not blindly repeated; unavailable members are not absence evidence.','Selected Core XML is not the fully patched active Def database.','Native runs distinguish developer preparation and ordinary consumption; cost/time/quality/probability are not calibrated.')}
[IO.File]::WriteAllText((Join-Path $out 'dining-comfort-evidence.json'),($e|ConvertTo-Json -Depth 18).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"$($claims.Count) claims; $($xml.Count) XML selections; $($manifest.types.Count) newly extracted types."
